
let tarefas = [];
let proximoCodigo = 1;

// CADASTRAR NOVA TAREFA
document.getElementById("formTarefa")
.addEventListener("submit", function(event) {

    event.preventDefault();

        let titulo = document.getElementById("titulo").value.trim();

            let descricao = document.getElementById("descricao").value.trim();

                let prioridade = Number(
                        document.getElementById("prioridade").value
                            );

                                let mensagem = document.getElementById("mensagem");

                                    // VALIDAR TÍTULO
                                        if (titulo.length < 5) {
                                                mensagem.textContent =
                                                            "O título deve ter no mínimo 5 caracteres!";
                                                                    return;
                                                                        }

                                                                            // VALIDAR DESCRIÇÃO
                                                                                if (descricao.length === 0) {
                                                                                        mensagem.textContent =
                                                                                                    "Digite uma descrição para a tarefa!";
                                                                                                            return;
                                                                                                                }

                                                                                                                    // VALIDAR PRIORIDADE
                                                                                                                        if (![1, 2, 3].includes(prioridade)) {
                                                                                                                                mensagem.textContent =
                                                                                                                                            "A prioridade deve ser 1, 2 ou 3!";
                                                                                                                                                    return;
                                                                                                                                                        }

                                                                                                                                                            // CRIAR OBJETO DA TAREFA
                                                                                                                                                                let tarefa = {
                                                                                                                                                                        codigo: proximoCodigo++,
                                                                                                                                                                                titulo: titulo,
                                                                                                                                                                                        descricao: descricao,
                                                                                                                                                                                                prioridade: prioridade,
                                                                                                                                                                                                        concluida: false
                                                                                                                                                                                                            };

                                                                                                                                                                                                                tarefas.push(tarefa);

                                                                                                                                                                                                                    mensagem.style.color = "green";
                                                                                                                                                                                                                        mensagem.textContent =
                                                                                                                                                                                                                                "Tarefa cadastrada com sucesso!";

                                                                                                                                                                                                                                    // LIMPAR CAMPOS
                                                                                                                                                                                                                                        document.getElementById("titulo").value = "";
                                                                                                                                                                                                                                            document.getElementById("descricao").value = "";

                                                                                                                                                                                                                                                listarTarefas();
                                                                                                                                                                                                                                                });


                                                                                                                                                                                                                                                // LISTAR TAREFAS
                                                                                                                                                                                                                                                function listarTarefas() {

                                                                                                                                                                                                                                                    let lista = document.getElementById("listaTarefas");

                                                                                                                                                                                                                                                        lista.innerHTML = "";

                                                                                                                                                                                                                                                            if (tarefas.length === 0) {
                                                                                                                                                                                                                                                                    lista.textContent = "Nenhuma tarefa cadastrada.";
                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                    tarefas.forEach(function(tarefa) {

                                                                                                                                                                                                                                                                                            let status = tarefa.concluida
                                                                                                                                                                                                                                                                                                        ? "Concluída"
                                                                                                                                                                                                                                                                                                                    : "Pendente";

                                                                                                                                                                                                                                                                                                                            let prioridadeTexto = {
                                                                                                                                                                                                                                                                                                                                        1: "Alta",
                                                                                                                                                                                                                                                                                                                                                    2: "Média",
                                                                                                                                                                                                                                                                                                                                                                3: "Baixa"
                                                                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                                                                                let div = document.createElement("div");

                                                                                                                                                                                                                                                                                                                                                                                        div.className = tarefa.concluida
                                                                                                                                                                                                                                                                                                                                                                                                    ? "tarefa concluida"
                                                                                                                                                                                                                                                                                                                                                                                                                : "tarefa";

                                                                                                                                                                                                                                                                                                                                                                                                                        // INFORMAÇÕES DA TAREFA
                                                                                                                                                                                                                                                                                                                                                                                                                                let informacoes = document.createElement("p");

                                                                                                                                                                                                                                                                                                                                                                                                                                        informacoes.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                    "Código: " + tarefa.codigo +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                " | Título: " + tarefa.titulo;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        div.appendChild(informacoes);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // DESCRIÇÃO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let textoDescricao = document.createElement("p");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                textoDescricao.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "Descrição: " + tarefa.descricao;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    div.appendChild(textoDescricao);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // PRIORIDADE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let textoPrioridade = document.createElement("p");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            textoPrioridade.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Prioridade: " + prioridadeTexto[tarefa.prioridade];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                div.appendChild(textoPrioridade);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // STATUS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let textoStatus = document.createElement("p");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        textoStatus.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "Status: " + status;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            div.appendChild(textoStatus);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // BOTÃO CONCLUIR
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let btnConcluir = document.createElement("button");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    btnConcluir.textContent = "Concluir";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            btnConcluir.className = "concluir";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    btnConcluir.disabled = tarefa.concluida;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            btnConcluir.onclick = function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        concluirTarefa(tarefa.codigo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        div.appendChild(btnConcluir);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // BOTÃO ALTERAR PRIORIDADE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let btnAlterar = document.createElement("button");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                btnAlterar.textContent = "Alterar prioridade";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        btnAlterar.className = "alterar";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                btnAlterar.onclick = function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            alterarPrioridade(tarefa.codigo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            div.appendChild(btnAlterar);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    lista.appendChild(div);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // MARCAR TAREFA COMO CONCLUÍDA
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function concluirTarefa(codigo) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let tarefa = tarefas.find(function(item) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return item.codigo === codigo;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (tarefa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    tarefa.concluida = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            listarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ALTERAR PRIORIDADE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function alterarPrioridade(codigo) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let tarefa = tarefas.find(function(item) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return item.codigo === codigo;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!tarefa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let novaPrioridade = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            prompt(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Digite a nova prioridade:\n" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "1 - Alta\n" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "2 - Média\n" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "3 - Baixa"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (![1, 2, 3].includes(novaPrioridade)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    alert("Prioridade inválida! Digite 1, 2 ou 3.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    tarefa.prioridade = novaPrioridade;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        listarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // EXIBIR LISTA INICIAL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        listarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        